window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1e6b48a531a36c79"]={"versions": [{"id": "FIG-1e6b48a531a36c79", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Metamodell-Beispieldiagramm (Objekt-/Instanzbeziehungsdarstellung) aus der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm illustriert die Modellierungsregeln und Referenzierungssemantik für <code>ServiceInterfaceSubElement</code> im Kontext einer Dienstschnittstelle (<code>ServiceInterface XYZ</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente und Relationen:</p>\n<ul class=\"fig-list\">\n<li><strong>ServiceInterface XYZ</strong>: Umfassender Scope der Dienstschnittstelle.</li>\n<li><strong>event</strong>: Drei exemplarische Instanzen von Ereignissen innerhalb des Service-Interface.</li>\n<li><strong>Datatype</strong>: Zentraler Datentyp, der durch die Events typisiert wird (<code>type</code>-Referenzen) und strukturell aus inneren Elementen besteht:</li>\n<li><code>DataPrototype (opt)</code>: Optionaler Sub-Datenelement-Prototyp.</li>\n<li><code>DataPrototype</code>: Weiterer Sub-Datenelement-Prototyp.</li>\n<li><strong>ServiceInterfaceSubElement</strong>: Drei Ausprägungen, jeweils mit Assoziationen:</li>\n<li><code>root</code>: Referenziert das übergeordnete Wurzelelement (<code>event</code>).</li>\n<li><code>target</code>: Referenziert das konkrete Datensubelement (<code>DataPrototype</code>).</li>\n<li><strong>Gültigkeitsmarkierungen</strong>: Grüne Häkchen kennzeichnen zulässige Referenzierungspfade; rote Kreuze kennzeichnen unzulässige Konfigurationen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Validierungs- und Zuordnungsschema für Metamodellreferenzen:</p>\n<ol class=\"fig-list\">\n<li>Ein <code>ServiceInterfaceSubElement</code> referenziert über die Assoziation <code>root</code> ein konkretes <code>event</code>.</li>\n<li>Das referenzierte <code>event</code> bestimmt über die Relation <code>type</code> den zugrunde liegenden Datentyp (<code>Datatype</code>).</li>\n<li>Die Referenz <code>target</code> des <code>ServiceInterfaceSubElement</code> muss auf ein Unterelement (<code>DataPrototype</code>) zeigen, das über den Typisierungspfad des durch <code>root</code> referenzierten Events erreichbar ist (grüne Häkchen).</li>\n<li>Zeigt <code>target</code> auf ein Unterelement oder einen Typ, der nicht im Pfad des via <code>root</code> referenzierten Events liegt, ist die Referenz ungültig (rote Kreuze).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikationsregel für die Modellierung von Service-Interface-Sub-Elementen in Manifesten:</p>\n<ul class=\"fig-list\">\n<li>Bei der Adressierung von Datenelementen innerhalb komplexer Ereignistypen via <code>ServiceInterfaceSubElement</code> müssen Wurzelreferenz (<code>root</code>) und Zielreferenz (<code>target</code>) semantisch konsistent sein.</li>\n<li><code>root</code> muss auf das konkrete Ereignis zeigen, dessen Datentyp den adressierten <code>DataPrototype</code> enthält.</li>\n<li>Unstimmige Paare, bei denen das referenzierte <code>target</code> nicht zum über <code>root</code> typisierten Datenbaum gehört, verletzen die Konsistenzbedingungen des Manifest-Metamodells.</li>\n</ul>"}, {"id": "FIG-bceb9b16556ad4cf", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Metamodell-Beispieldiagramm (Objekt-/Instanzbeziehungsdarstellung) aus der AUTOSAR Adaptive Platform (TPS Manifest Specification). Das Diagramm illustriert die Modellierungsregeln und Referenzierungssemantik für <code>ServiceInterfaceSubElement</code> im Kontext einer Dienstschnittstelle (<code>ServiceInterface XYZ</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Modellelemente und Relationen:</p>\n<ul class=\"fig-list\">\n<li><strong>ServiceInterface XYZ</strong>: Umfassender Scope der Dienstschnittstelle.</li>\n<li><strong>event</strong>: Drei exemplarische Instanzen von Ereignissen innerhalb des Service-Interface.</li>\n<li><strong>Datatype</strong>: Zentraler Datentyp, der durch die Events typisiert wird (<code>type</code>-Referenzen) und strukturell aus inneren Elementen besteht:</li>\n<li><code>DataPrototype (opt)</code>: Optionaler Sub-Datenelement-Prototyp.</li>\n<li><code>DataPrototype</code>: Weiterer Sub-Datenelement-Prototyp.</li>\n<li><strong>ServiceInterfaceSubElement</strong>: Drei Ausprägungen, jeweils mit Assoziationen:</li>\n<li><code>root</code>: Referenziert das übergeordnete Wurzelelement (<code>event</code>).</li>\n<li><code>target</code>: Referenziert das konkrete Datensubelement (<code>DataPrototype</code>).</li>\n<li><strong>Gültigkeitsmarkierungen</strong>: Grüne Häkchen kennzeichnen zulässige Referenzierungspfade; rote Kreuze kennzeichnen unzulässige Konfigurationen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Validierungs- und Zuordnungsschema für Metamodellreferenzen:</p>\n<ol class=\"fig-list\">\n<li>Ein <code>ServiceInterfaceSubElement</code> referenziert über die Assoziation <code>root</code> ein konkretes <code>event</code>.</li>\n<li>Das referenzierte <code>event</code> bestimmt über die Relation <code>type</code> den zugrunde liegenden Datentyp (<code>Datatype</code>).</li>\n<li>Die Referenz <code>target</code> des <code>ServiceInterfaceSubElement</code> muss auf ein Unterelement (<code>DataPrototype</code>) zeigen, das über den Typisierungspfad des durch <code>root</code> referenzierten Events erreichbar ist (grüne Häkchen).</li>\n<li>Zeigt <code>target</code> auf ein Unterelement oder einen Typ, der nicht im Pfad des via <code>root</code> referenzierten Events liegt, ist die Referenz ungültig (rote Kreuze).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikationsregel für die Modellierung von Service-Interface-Sub-Elementen in Manifesten:</p>\n<ul class=\"fig-list\">\n<li>Bei der Adressierung von Datenelementen innerhalb komplexer Ereignistypen via <code>ServiceInterfaceSubElement</code> müssen Wurzelreferenz (<code>root</code>) und Zielreferenz (<code>target</code>) semantisch konsistent sein.</li>\n<li><code>root</code> muss auf das konkrete Ereignis zeigen, dessen Datentyp den adressierten <code>DataPrototype</code> enthält.</li>\n<li>Unstimmige Paare, bei denen das referenzierte <code>target</code> nicht zum über <code>root</code> typisierten Datenbaum gehört, verletzen die Konsistenzbedingungen des Manifest-Metamodells.</li>\n</ul>"}], "trans": [{"from": "FIG-1e6b48a531a36c79", "to": "FIG-bceb9b16556ad4cf", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
